(* [comment removed for export] *)
Fixpoint ro_below (segs : list Segment) (lo hi : Z) : bool :=
  match segs with
  | [] => true
  | s :: r => (seg_writable s || ((lo <=? Z.of_N (seg_base s)) && (Z.of_N (seg_base s) + Z.of_N (seg_size s) <=? hi))) && ro_below r lo hi
  end.
Lemma ro_below_sound segs lo hi x : ro_below segs lo hi = true ->
  (match find_segment segs x 1 with Some seg => negb (seg_writable seg) | None => false end) = true -> lo <= x < hi.
Proof.
