Lemma bytes_at_of_rdn : forall m (a : Z) (bs : list byte),
  rdn rsegs m (Z_to_bv 64 a) (length bs) = Some bs -> 0 <= a -> a + Z.of_nat (length bs) <= 2 ^ 64 ->
  Mem.bytes_at rsegs m a bs.
