(* [comment removed for export] *)
Definition strtod_runA2 (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (sp ra tp s endp n : Z) (bs : list Z),
    getr R 2%bv = Z_to_bv 64 sp -> getr R 1%bv = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R 4%bv = Z_to_bv 64 tp -> tp = TP_A ->
    getr R 10%bv = Z_to_bv 64 s -> getr R 11%bv = Z_to_bv 64 endp ->
    Z.of_nat (length bs) = n -> 1 <= n <= WDL.SNP_MAX -> (WDL.gnum bs = true \/ WDL.gspecial bs) -> Forall (fun c => 0 <= c < 256) bs ->
    L5.bytes_at RSEGS M s (bs ++ [0]) -> frm_zero (@fp_csr fx) ->
    VA.IMG_HI_A + VA.STRTOD_SCR <= sp -> sp <= 2 ^ 47 -> sp mod 16 = 0 -> VA.bigapart (sp - VA.STRTOD_SCR) VA.STRTOD_SCR ->
    L5.writable RSEGS M (sp - VA.STRTOD_SCR) VA.STRTOD_SCR -> L5.defined M (sp - VA.STRTOD_SCR) VA.STRTOD_SCR ->
    VA.IMG_HI_A <= s -> s + n + 1 <= 2 ^ 47 -> VA.bigapart s (n + 1) -> (sp <= s \/ s + n + 1 <= sp - VA.STRTOD_SCR) ->
    VA.IMG_HI_A <= endp -> endp + 8 <= 2 ^ 47 -> VA.bigapart endp 8 -> (sp <= endp \/ endp + 8 <= sp - VA.STRTOD_SCR) -> (endp + 8 <= s \/ s + n + 1 <= endp) ->
    L5.writable RSEGS M endp 8 -> L5.defined M endp 8 ->
    L5.writable RSEGS M (tp - VA.ERRNO_OFF) 4 ->
    L5.img_clear M 0x10000 0x158000 ->
    exists (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte),
      mem_grows M M'
      /\ (forall a : word, ~ (sp - VA.STRTOD_SCR <= bv_unsigned a < sp) -> ~ (endp <= bv_unsigned a < endp + 8) ->
                           ~ (tp - VA.ERRNO_OFF <= bv_unsigned a < tp - VA.ERRNO_OFF + 4) -> M' a = M a)
      /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (sp - VA.STRTOD_SCR <= i < sp) -> ~ (endp <= i < endp + 8) ->
                         ~ (tp - VA.ERRNO_OFF <= i < tp - VA.ERRNO_OFF + 4) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
      /\ CatSim.msteps RSEGS (st fx R pc M) (st fx' R' ra M')
      /\ (forall x, In x VA.LIBC_CS -> getr R' (reg x) = getr R (reg x))
      /\ L5.u64_at RSEGS M' endp (s + n) /\ L5.bytes_at RSEGS M' s (bs ++ [0])
      /\ L5.defined M' (sp - VA.STRTOD_SCR) VA.STRTOD_SCR /\ frm_zero (@fp_csr fx').

(* [comment removed for export] *)
Lemma strtod_runA2_shape pc : strtod_runA2 pc ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (sp ra s endp n : Z) (bs : list Z),
    getr R 4%bv = Z_to_bv 64 TP_A -> True.
Proof.
ltac2:(KReplay.run1 (kr_t_WaStBridge ()) [] "h02pch11Mh21Rh32bsh44endph52fxh61nh72rah81sh92spp;1p;2p;3p-1p10000p4p710p8p1000Gp4p710R0p1000dp4p710R1p8P0p1001@p4p710R0p8p1001^p4p710R2P1p8P2p1002ip4p710p8P2p1003Gp4p710p8P2p1003fp4p7210p8P2P0p8P2p1004Cp4p710p8P2p1004ep4p710p8g005@R2p4p7210R3P1p8P3P0p8p1005lp4p7210R3P1p8P3P0p8p1006Ip4p710P0p8g009Xj1<Tg00:aj10Tg00;Fj14Tg00;kj11Tg00<Ij12TP2j2;Tg00<lj1:Tg00=Nj15Tg00=nj16Tg00>Lj37Tg00>oj23Tg00?aj28Tg00@Gj39Tg008=R2f0R0#<g00@ag00AX#0R3#4#1R1%03R3#0R4#0#0#0#1R5#2R6';%14#2#:\6%52f7%63g00B=R3571'3g00BY,85596P3UW3X62X42X82X72X92W1W2W5UX02P0O1W0o"). Qed.

