Lemma vsnprintf_walk0 : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo argz prec d dst : Z) (obuf jp jva : list byte) (G : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> WAI.senv m lo -> WAI.tush m dst -> (lo + 5968 <= bv_unsigned sp)%Z -> (bv_unsigned sp < 2 ^ 63)%Z -> (0x6b3d78 <= lo)%Z -> (bv_unsigned ra mod 2 = 0)%Z ->
  (bv_unsigned sp <= lo + WAI.WIN)%Z -> (argz + 40 <= lo + WAI.WIN)%Z -> (bv_unsigned sp mod 16 = 0)%Z ->
  ro_cells rsegs m 0x157b38 [C8 (Z_to_bv 64 0x6b3b40)] -> ro_cells rsegs m 0x6b3b40 [C8 G] ->
  u8arr rsegs m dst obuf -> length obuf = 100%nat ->
  rw_cells rsegs m argz [C4 (Z_to_bv 64 prec); CB 4 jp; C8 (Z_to_bv 64 d); CB 24 jva] ->
  (prec = 15 \/ prec = 17)%Z -> (0 <= d < 2 ^ 64)%Z -> (d mod 2 ^ 63 <> 0)%Z ->
  (dst + 100 <= lo \/ bv_unsigned sp <= dst)%Z -> (bv_unsigned sp <= argz)%Z -> (dst + 100 < 2 ^ 63)%Z -> (argz + 16 < 2 ^ 63)%Z ->
  (argz + 40 <= dst \/ dst + 100 <= argz)%Z -> (0x6b6000 <= dst)%Z -> (dst + 100 <= 2147446784 \/ 17594333495296 <= dst)%Z ->
  a0 = Z_to_bv 64 dst -> a1 = Z_to_bv 64 100 -> a2 = Z_to_bv 64 0x23c40 -> a3 = Z_to_bv 64 argz ->
  evt rsegs (fun ms' => exists (bs : list byte) t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' F' fc' m',
      (WDL.gnum (zs bs) = true \/ WDL.gspecial (zs bs)) /\ (1 <= Z.of_nat (length bs) <= 26)%Z /\
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (Z.of_nat (length bs))) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F'
               (ret_pc ra) fc' None m' (seg_rom rsegs)
      /\ fkeep F F'
      /\ munch [(lo, bv_unsigned sp); (dst, dst + 100)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ u8arr rsegs m' dst (upd_bytes obuf 0 (bs ++ [Z_to_bv 8 0])))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0x14686c) fc None m (seg_rom rsegs)).
Proof.
